const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[n]||[]).map(([t,a])=>'<'+t+' '+Object.entries(a).map(([k,v])=>k+'="'+v+'"').join(' ')+'/>').join('')+'</svg>';
const pages=[['accueil','Tableau de bord','House'],['cours','Mes cours','BookOpen'],['agenda','Mon agenda','CalendarDays'],['dossiers','Mes candidatures','FolderOpen'],['catalogue','Catalogue','Compass'],['espaces','Tous les espaces','Layers'],['reference','Référentiel TdR','Library']];
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem('unoa-demo-3/'+k))??d}catch{return d}};
const save=(k,v)=>localStorage.setItem('unoa-demo-3/'+k,JSON.stringify(v));
const progress=i=>get('progress'+i,courses[i].start);
const link=(r,t,cl='secondary')=>'<a class="'+cl+'" href="#'+r+'">'+t+'</a>';
const button=(a,t,n='',cl='secondary')=>'<button class="'+cl+'" data-act="'+a+'" data-n="'+esc(n)+'">'+t+'</button>';
const title=(k,t,sub='')=>'<div class="intro"><div class="eyebrow">'+k+'</div><h1 class="page">'+t+'</h1>'+(sub?'<p class="muted">'+sub+'</p>':'')+'</div>';
const sec=(t,r,l)=>'<div class="sectionHead"><h2>'+t+'</h2>'+(r?link(r,l+' '+icon('ArrowUpRight'),''): '')+'</div>';
function card(c,i){let p=Math.round(100*progress(i)/c.units.length);return link('cours/'+i,'<div class="art a'+i+'">'+icon(c.icon)+'</div><div class="body"><small>'+c.category+'</small><h3>'+c.title+'</h3><div class="progress"><span class="track"><i style="width:'+p+'%"></i></span>'+p+' %</div></div>','card')}
function eventRows(){return '<div class="panel">'+events.map(([day,month,t,h,type],i)=>'<div class="row"><div class="date">'+month+'<b>'+day+'</b></div><div><h3>'+t+'</h3><small>'+h+' · Cotonou</small></div><span class="tag">'+type+'</span>'+button('event',icon('ArrowUpRight')+'<span class="sr">Détails de '+t+'</span>',i,'plain')+'</div>').join('')+'</div>'}
function home(){return '<section class="hero"><img src="campus.webp" alt=""><div class="copy"><div class="eyebrow">CAMPUS DU BÉNIN · ESPACE ÉTUDIANT</div><h1>Bonjour, Koffi.</h1><p>Retrouvez vos cours et les prochains rendez-vous de votre semaine.</p>'+link('cours/'+Math.max(0,courses.findIndex((c,i)=>progress(i)<c.units.length)),icon('Play')+' Reprendre un cours','cta')+'</div></section>'+sec('Mes cours','cours','Voir mes cours')+'<div class="grid">'+courses.map(card).join('')+'</div>'+sec('Prochains rendez-vous','agenda','Voir l’agenda')+eventRows()}
function course(i){const c=courses[i],p=progress(i);return title('MES COURS',c.title,c.category+' · '+p+' séquence(s) terminée(s) sur '+c.units.length)+'<div class="stack">'+c.units.map((u,j)=>'<div class="panel row"><span class="avatar">'+(j+1)+'</span><div><h3>'+u+'</h3><small>'+(j<p?'Terminée':j===p?'À suivre':'À venir')+'</small></div>'+button('lesson',j<p?'Relire':'Consulter',i+'-'+j)+'</div>').join('')+'</div>'}
function catalogue(){return title('ORIENTATION','Catalogue des formations','Offres fictives pour tester l’orientation et la candidature.')+'<div class="tools"><input id="filter" type="search" aria-label="Rechercher une formation" placeholder="Rechercher une formation"><select id="cycle" aria-label="Cycle"><option>Tous les cycles</option>'+programs.map(p=>'<option>'+p[0]+'</option>').join('')+'</select>'+button('compare','Comparer la sélection')+'</div><div class="grid" id="results"></div>'}
let selection=new Set();
function filterPrograms(){let q=$('filter').value.toLocaleLowerCase(),cycle=$('cycle').value;$('results').innerHTML=programs.map(([c,t,cr,stat],i)=>((cycle==='Tous les cycles'||c===cycle)&&(t+' '+c).toLowerCase().includes(q))?'<article class="tile"><span class="tag">'+c+'</span><h3 style="margin-top:12px">'+t+'</h3><p>'+cr+' · '+stat+'</p><label><input type="checkbox" data-compare="'+i+'" '+(selection.has(i)?'checked':'')+'> Comparer</label><div class="tools">'+button('apply','Candidater',i)+'</div></article>':'').join('')||'<p>Aucune formation correspondante.</p>'}
const dossiers=()=>get('dossiers',[]);
function applications(staff){let ds=dossiers();return title(staff?'SCOLARITÉ':'ADMISSIONS',staff?'Instruction des dossiers':'Mes candidatures','Les dossiers de démonstration sont enregistrés dans ce navigateur.')+(staff?'':link('catalogue','Choisir une formation','cta'))+sec('Dossiers')+(ds.length?ds.map((d,i)=>'<article class="panel pad"><small>Dossier '+(i+1)+'</small><h3>'+programs[d.p][1]+'</h3><p class="status">'+esc(d.state)+'</p>'+(d.note?'<p>'+esc(d.note)+'</p>':'')+(staff&&d.state==='Transmis'?button('review','Instruire',i):!staff&&['Brouillon','Complément demandé'].includes(d.state)?button('edit','Compléter le dossier',i):'')+'</article>').join(''):'<div class="panel pad">Aucun dossier '+(staff?'à instruire.':'ouvert. Votre prochaine candidature apparaîtra ici.')+'</div>')}
function spaces(){return title('UNIVERSITÉ','Tous les espaces','Choisissez un rôle pour tester son parcours avec des données fictives.')+'<div class="grid">'+roles.map(([k,n,ic,,a])=>link('espace/'+k,icon(ic)+'<h3>'+n+'</h3><p>'+a+'</p>','tile')).join('')+'</div>'}
function role(r){let items=get('work'+r[0],[]);return title('ESPACE MÉTIER',r[1])+((r.length===6)?link(r[5],r[4],'cta'):button('work',r[4],r[0],'cta'))+(r.length>6?sec('Dossiers de travail')+'<div class="panel pad">'+(items.length?items.map((it,i)=>'<div class="row"><div><b>'+esc(it.t)+'</b><small>'+esc(it.s)+'</small></div>'+(it.s===r[6]?button('move','Transmettre',r[0]+'-'+i):'')+'</div>').join(''):'Aucun dossier créé dans cet espace.')+'</div>':'')+sec('Parcours et écrans prévus')+'<div class="stack">'+domains.filter(d=>r[3].split(' ').includes(d.code)).map(domain).join('')+'</div>'}
function domain(d){return '<details><summary>'+esc(d.name)+' <span class="metric">· '+d.code+'</span></summary><p>'+esc(d.flow)+'</p><p><b>Écrans prévus</b><br>'+esc(d.screens)+'</p><p><b>Cas à tester</b><br>'+esc(d.errors)+'</p><details><summary>'+d.req.length+' exigences à vérifier</summary>'+d.req.map(([k,t])=>'<p><small>'+k+'</small>'+esc(t)+'</p>').join('')+'</details></details>'}
function ref(){return title('CONCEPTION','Référentiel des TdR','44 domaines et 533 exigences de la version 2.0. Chaque fiche décrit le périmètre cible à vérifier lors du développement.')+'<div class="tools"><input id="domainFilter" type="search" aria-label="Rechercher un domaine ou une exigence" placeholder="Domaine, mot ou identifiant REQ…"></div><div class="stack" id="domainResults"></div>'}
function filterDomains(){let q=$('domainFilter').value.toLowerCase();$('domainResults').innerHTML=domains.filter(d=>JSON.stringify(d).toLowerCase().includes(q)).map(domain).join('')||'Aucun domaine correspondant.'}
function modal(html){$('inside').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function close(){if($('modal').open)$('modal').close()}
function render(){close();document.body.classList.remove('open');let [k,id]=(location.hash.slice(1)||'accueil').split('/'),entry=pages.find(p=>p[0]===k),r=roles.find(r=>r[0]===id);if(k==='espace'&&r)entry=pages[5];if(k==='instruction')entry=pages[5];if(!entry){location.hash='accueil';return}let html;
switch(k){case 'accueil':html=home();break;case 'cours':html=id!==undefined&&courses[id]?course(+id):title('ESPACE ÉTUDIANT','Mes cours')+'<div class="grid">'+courses.map(card).join('')+'</div>';break;case 'agenda':html=title('ESPACE ÉTUDIANT','Mon agenda','Novembre 2026 · Heure locale de Cotonou')+eventRows();break;case 'catalogue':html=catalogue();break;case 'dossiers':case 'instruction':html=applications(k==='instruction');break;case 'espaces':html=spaces();break;case 'espace':html=role(r);break;case 'reference':html=ref();break}
$('here').textContent=k==='espace'?r[1]:k==='instruction'?'Instruction':entry[1];document.title=$('here').textContent+' · UNOA';$('content').innerHTML=html;document.querySelectorAll('.nav').forEach(a=>{a.classList.toggle('active',a.hash==='#'+entry[0]);if(a.classList.contains('active'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(k==='catalogue'){filterPrograms();$('filter').oninput=filterPrograms;$('cycle').onchange=filterPrograms}if(k==='reference'){filterDomains();$('domainFilter').oninput=filterDomains}window.scrollTo(0,0)}
function refresh(){close();render()}
function search(){modal('<h2>Rechercher dans le campus</h2><input id="global" type="search" placeholder="Cours, formation, espace…" aria-label="Recherche globale"><div id="matches" class="stack"></div>');const choices=[...pages.map(p=>[p[0],p[1]]),...courses.map((c,i)=>['cours/'+i,c.title]),...roles.map(r=>['espace/'+r[0],r[1]]),...programs.map(p=>['catalogue',p[1]])];function update(){$('matches').innerHTML=choices.filter(c=>c[1].toLowerCase().includes($('global').value.toLowerCase())).slice(0,9).map(c=>link(c[0],c[1],'nav')).join('')||'Aucun résultat.'}$('global').oninput=update;update();$('global').focus()}
const lessons=[
 ['Un jeu de données organise des observations en lignes et des variables en colonnes. Repérez l’unité de mesure de chaque variable.','Recherchez les valeurs manquantes et les doublons avant de calculer une moyenne.','Comparez les médianes et la dispersion de deux groupes. Des moyennes proches peuvent masquer des distributions différentes.',courses[0].lesson,'Lisez les axes, les unités et l’échelle avant de formuler une conclusion.'],
 ['Décrivez les objets à représenter, par exemple un étudiant et une inscription.',courses[1].lesson,'Une inscription relie un étudiant à une offre de formation. Chaque ligne porte les identifiants correspondants.','Vérifiez les contraintes de type, d’unicité et de référence sur chaque table.'],
 ['Une variable associe un nom à une valeur. Une chaîne de caractères et un entier peuvent représenter des informations différentes.','Une condition sélectionne une branche du programme selon la valeur vraie ou fausse d’une expression.',courses[2].lesson,'Une fonction peut recevoir des arguments et retourner une valeur. Donnez-lui une responsabilité clairement définie.','Écrivez une fonction qui retourne la moyenne d’une liste de nombres. Prévoyez le cas d’une liste vide.']
];
document.addEventListener('click',e=>{const a=e.target.closest('[data-act]');if(e.target.closest('a')){close();document.body.classList.remove('open')}if(!a)return;const n=a.dataset.n,i=Number(n),ds=dossiers();
switch(a.dataset.act){
 case 'event':modal('<h2>'+events[i][2]+'</h2><p>'+events[i][0]+' novembre · '+events[i][3]+'</p><p>'+events[i][5]+'</p>'+(i===1?button('assignment','Ouvrir le travail'):'') );break;
 case 'assignment':modal('<h2>Modèle relationnel</h2><label>Votre proposition<textarea id="draft">'+esc(get('assignment',''))+'</textarea></label>'+button('saveAssignment','Enregistrer le travail'));break;
 case 'saveAssignment':save('assignment',$('draft').value);modal('<h2>Travail enregistré</h2><p>Votre proposition est conservée dans ce navigateur.</p>');break;
 case 'lesson':{let [c,j]=n.split('-').map(Number);modal('<div class="eyebrow">SÉQUENCE '+(j+1)+'</div><h2>'+courses[c].units[j]+'</h2><p>'+lessons[c][j]+'</p>'+(progress(c)===j?button('finish','Marquer comme terminée',c+'-'+j,'cta'):progress(c)<j?'<small>Terminez les séquences précédentes pour valider celle-ci.</small>':'<span class="tag">Terminée</span>'));break}
 case 'finish':{let [c,j]=n.split('-').map(Number);if(progress(c)===j)save('progress'+c,j+1);refresh();break}
 case 'compare':modal('<h2>Comparer les formations</h2>'+(selection.size>1?[...selection].map(i=>'<div class="panel pad"><small>'+programs[i][0]+'</small><b>'+programs[i][1]+'</b><p>'+programs[i][2]+' · '+programs[i][3]+'</p></div>').join(''):'<p>Cochez au moins deux formations dans le catalogue.</p>'));break;
 case 'apply':if(!ds.some(d=>d.p===i)){ds.push({p:i,state:'Brouillon',note:'',piece:false});save('dossiers',ds)}location.hash='dossiers';break;
 case 'edit':modal('<h2>Compléter la candidature</h2><p>'+programs[ds[i].p][1]+'</p><label><input id="piece" type="checkbox" '+(ds[i].piece?'checked':'')+'> Joindre le justificatif fictif</label><div class="tools">'+button('draft','Sauvegarder',i)+button('submit','Vérifier et transmettre',i,'cta')+'</div><p id="feedback" role="status"></p>');break;
 case 'draft':case 'submit':{ds[i].piece=$('piece').checked;if(a.dataset.act==='submit'&&!ds[i].piece){$('feedback').textContent='Ajoutez le justificatif avant de transmettre le dossier.';break}save('dossiers',ds);if(a.dataset.act==='draft')refresh();else modal('<h2>Confirmer la transmission</h2><p>'+programs[ds[i].p][1]+' · Justificatif joint</p>'+button('confirm','Transmettre à la scolarité',i,'cta'));break}
 case 'confirm':ds[i].state='Transmis';save('dossiers',ds);refresh();break;
 case 'review':modal('<h2>Décision sur le dossier</h2><p>'+programs[ds[i].p][1]+'</p><label>Décision simulée<select id="decision"><option>Complément demandé</option><option>Admission proposée</option><option>Refus motivé</option></select></label><label>Motif ou pièce attendue<textarea id="motif" required></textarea></label>'+button('decide','Confirmer la décision',i,'cta'));break;
 case 'decide':if(!$('motif').reportValidity())break;ds[i].state=$('decision').value;ds[i].note=$('motif').value;if(ds[i].state==='Complément demandé')ds[i].piece=false;save('dossiers',ds);refresh();break;
 case 'work':{let r=roles.find(x=>x[0]===n);modal('<h2>'+r[5]+'</h2><label>Intitulé<input id="workTitle" required maxlength="160"></label><div class="tools">'+button('saveWork','Enregistrer',n,'cta')+'</div>');break}
 case 'saveWork':{if(!$('workTitle').value.trim()){ $('workTitle').value='';$('workTitle').reportValidity();break}let r=roles.find(x=>x[0]===n),items=get('work'+n,[]);items.push({t:$('workTitle').value.trim(),s:r[6]});save('work'+n,items);refresh();break}
 case 'move':modal('<h2>Confirmer la transmission</h2><p>Le dossier passera à la prochaine étape de revue.</p>'+button('confirmMove','Confirmer',n,'cta'));break;
 case 'confirmMove':{let [key,id]=n.split('-'),items=get('work'+key,[]);items[id].s=roles.find(x=>x[0]===key)[7];save('work'+key,items);refresh();break}
}});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-compare')){let i=Number(e.target.dataset.compare);e.target.checked?selection.add(i):selection.delete(i)}});
function nav(p){return link(p[0],icon(p[2])+p[1],'nav')}
$('nav').innerHTML=pages.slice(0,4).map(nav).join('');$('uni').innerHTML=pages.slice(4).map(nav).join('');$('search').innerHTML=icon('Search');$('search').onclick=search;$('menu').onclick=()=>document.body.classList.toggle('open');$('close').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('open')});window.addEventListener('hashchange',()=>{render();$('content').focus({preventScroll:true})});render();
document.querySelector('.skip').onclick=e=>{e.preventDefault();$('content').focus()};
document.addEventListener('click',e=>{if(document.body.classList.contains('open')&&!e.target.closest('aside,#menu'))document.body.classList.remove('open')});
